FREE_WITNESS = '00521 00526 03216 03403 03565 04111 04203 04415 04460 04660 10021 10026 11220 11225 12424 12511 14236 14510 14615 15156 15522 15530 15602 16006 20425 23023 23115 24010 24102 25030 25206 26221 26226 26650 30620 33430 33514 34135 34406 34501 36605 41515 41665 43014 44626 44634 53413 53505 54061 54121 54213 54400 54425 55666 63540 64016 64246 64624 65530'
def words(text):
    result = [tuple(map(int, w)) for w in text.split()]
    assert all(len(w) == 5 and all(0 <= x < 7 for x in w) for w in result)
    return result
core, boxes, extra = map(words, (CORE, BOXES, FREE_WITNESS))
assert len(core) == len(set(core)) == 308 and len(boxes) == 367
witness = core + extra
assert len(witness) == len(set(witness)) == 367
for a, b in combinations(witness, 2):
    assert any((x-y) % 7 in (2,3,4,5) for x,y in zip(a,b))
blocked = {w: 0 for w in product(range(7), repeat=5)}
for w in core:
    for v in product(*[((x-1)%7, x, (x+1)%7) for x in w]):
        blocked[v] += 1
U1 = {w for w, n in blocked.items() if n <= 1}
assert len(U1) == 896 and set(witness) <= U1
covered = set()
for origin in boxes:
    covered.update(product(*[(x, (x+1)%7) for x in origin]))
assert U1 <= covered
print('Verified: 896 vertices covered by 367 cliques; independent witness 367.')
print('Therefore alpha(U1) = 367, with the fixed 308-word core used to define U1.')
